import{c as a,Q as n,j as s,m as t}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Beyond Task Success: An Evidence-Synthesis Framework for Evaluating, Governing, and Orchestrating Agentic AI","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.19818","title":"Beyond Task Success: An Evidence-Synthesis Framework for Evaluating, Governing, and Orchestrating Agentic AI","archived_date":"2026-07-30T00:00:00.000Z","arxiv_id":2604.19818,"authors":["Christopher Koch","Joshua Andreas Wellbrock"],"collected_at":"2026-07-30T00:00:00.000Z","collected_by":"routine-d","domain":"harness-engineering","pdf_path":"pdfs/2604.19818.pdf","published_date":"2026-04-18T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-18-beyond-task-success-evidence-synthesis-governance-2604-19818.md","filePath":"research/papers/2026-04-18-beyond-task-success-evidence-synthesis-governance-2604-19818.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-04-18-beyond-task-success-evidence-synthesis-governance-2604-19818.md"};function c(o,e,i,d,h,l){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="beyond-task-success-an-evidence-synthesis-framework-for-evaluating-governing-and-orchestrating-agentic-ai" tabindex="-1">Beyond Task Success: An Evidence-Synthesis Framework for Evaluating, Governing, and Orchestrating Agentic AI <a class="header-anchor" href="#beyond-task-success-an-evidence-synthesis-framework-for-evaluating-governing-and-orchestrating-agentic-ai" aria-label="Permalink to &quot;Beyond Task Success: An Evidence-Synthesis Framework for Evaluating, Governing, and Orchestrating Agentic AI&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>綜合 24 篇近期文獻，指出 agentic AI 部署的核心缺口：評測與治理框架各自獨立存在，未連結到具體 runtime 動作或合規驗證（governance-to-action closure gap）。提出三項產出：① 四層框架，整合評測/治理/編排/保證橫跨 agentic 系統全生命週期；② ODTA runtime-placement test，以 observability／decidability／timeliness／attestability 四準則評估控制手段是否可實作；③ Minimum Action-Evidence Bundle，規範 agent 狀態改變動作所需的最小證據文件。發現：評測研究將安全性/穩健性/軌跡層級量測列為未解缺口；治理框架定義義務但缺少執行期控制邏輯；文字層級的對齊不可靠地轉移到工具動作層級。以企業採購 agent 情境為例說明概念，未引入新實驗數據。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>「governance-to-action closure gap」精準對應本 workspace core.md 判斷 vs 決定公理與 <code>core.md §PROPOSE 委派</code>（原 <code>graph.md §G4</code>） Handoff Contract 的 Done-when／Return 契約設計初衷——治理意圖若不落地為 runtime 可驗證的最小證據，就只是紙面規範；ODTA 四準則可作為稽核既有 <code>[E]</code>/未標二分（原 <code>[E*]</code>，v5.1 廢除三分類） gate「缺哪個 Body」時的外部檢核清單。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</p>',5)])])}const v=a(r,[["render",c]]);export{u as __pageData,v as default};
